import React, { useState, useEffect, useRef } from "react";
import { getMatches, getTeamComparison } from "../api";

function ComparePage() {
  const [allTeams, setAllTeams] = useState([]);
  const [team1, setTeam1] = useState("");
  const [team2, setTeam2] = useState("");
  const [comparisonData, setComparisonData] = useState(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState("");

  // Рефы для управления фокусом
  const input1Ref = useRef(null);
  const input2Ref = useRef(null);

  useEffect(() => {
    const fetchTeams = async () => {
      const data = await getMatches(null);
      const teamSet = new Set();
      data.forEach((m) => {
        if (m.homeTeam?.name) teamSet.add(m.homeTeam.name);
        if (m.homeTeam?.name_ru) teamSet.add(m.homeTeam.name_ru);
        if (m.awayTeam?.name) teamSet.add(m.awayTeam.name);
        if (m.awayTeam?.name_ru) teamSet.add(m.awayTeam.name_ru);
      });
      setAllTeams(Array.from(teamSet).sort());
    };
    fetchTeams();
  }, []);

  const handleCompare = async () => {
    if (!team1 || !team2) {
      setError("Выберите обе команды для сравнения");
      return;
    }
    setLoading(true);
    setError("");
    const data = await getTeamComparison(team1, team2);
    if (data) {
      setComparisonData(data);
    } else {
      setError("Команды не найдены в базе данных");
    }
    setLoading(false);
  };

  // Переход по Enter: с 1-го на 2-й инпут
  const handleKeyDown1 = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      input2Ref.current.focus();
    }
  };

  // Переход по Enter: со 2-го инпута на запуск сравнения
  const handleKeyDown2 = (e) => {
    if (e.key === "Enter") {
      e.preventDefault();
      handleCompare();
    }
  };

  const ResultCircle = ({ res }) => {
    const colors = { W: "bg-green-500", D: "bg-yellow-500", L: "bg-red-600" };
    return (
      <span
        className={`${colors[res]} w-6 h-6 rounded-full flex items-center justify-center text-[10px] font-black text-white shadow-lg`}
      >
        {res}
      </span>
    );
  };

  return (
    <div className="max-w-5xl mx-auto px-4 py-8 text-white font-sans">
      {/* 1. ПАНЕЛЬ ВЫБОРА КОМАНД */}
      <div className="bg-gray-900 p-8 rounded-[32px] border border-gray-800 shadow-2xl mb-12">
        <div className="flex flex-col md:flex-row items-center justify-between gap-6">
          <div className="w-full md:w-2/5">
            <input
              ref={input1Ref}
              type="text"
              list="teams-list"
              value={team1}
              onChange={(e) => setTeam1(e.target.value)}
              onKeyDown={handleKeyDown1}
              autoComplete="off" // Убирает системные значки
              placeholder="Первая команда..."
              className="w-full bg-gray-950 border border-gray-800 rounded-2xl py-4 px-6 text-base text-white focus:outline-none focus:border-red-600 transition-all placeholder:text-gray-700"
            />
          </div>

          <button
            onClick={handleCompare}
            className="flex-shrink-0 w-16 h-16 bg-red-600 hover:bg-red-700 rounded-full flex items-center justify-center transition-all shadow-[0_0_20px_rgba(220,38,38,0.4)] group"
          >
            <svg
              className={`w-8 h-8 text-white transition-transform duration-500 ${loading ? "animate-spin" : "group-hover:rotate-180"}`}
              fill="none"
              stroke="currentColor"
              viewBox="0 0 24 24"
            >
              <path
                strokeLinecap="round"
                strokeLinejoin="round"
                strokeWidth="3"
                d="M8 7h12m0 0l-4-4m4 4l-4 4m0 6H4m0 0l4 4m-4-4l4-4"
              />
            </svg>
          </button>

          <div className="w-full md:w-2/5">
            <input
              ref={input2Ref}
              type="text"
              onChange={(e) => setTeam2(e.target.value)}
              onKeyDown={handleKeyDown2}
              placeholder="Вторая команда..."
              className="w-full bg-gray-950 border border-gray-800 rounded-2xl py-4 px-6 text-base text-white focus:outline-none focus:border-red-600 transition-all placeholder:text-gray-700"
            />
          </div>
        </div>
        <datalist id="teams-list">
          {allTeams.map((t, i) => (
            <option key={i} value={t} />
          ))}
        </datalist>
      </div>

      {error && (
        <div className="text-center text-red-500 font-black uppercase tracking-widest mb-10 bg-red-500/10 py-4 rounded-2xl border border-red-500/20">
          {error}
        </div>
      )}

      {/* 2. РЕЗУЛЬТАТЫ СРАВНЕНИЯ */}
      {comparisonData && !loading && (
        <div className="animate-in fade-in slide-in-from-bottom-4 duration-700">
          {/* ШАПКА: КОМАНДЫ, ЖЕЛТЫЙ ELO И ФОРМА */}
          <div className="flex flex-col md:flex-row justify-between items-center bg-gray-900 p-8 md:p-12 rounded-[32px] border border-gray-800 shadow-2xl relative overflow-hidden mb-10">
            <div className="flex flex-col items-center w-full md:w-2/5">
              <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-4 py-1.5 rounded-full mb-4 tracking-widest border border-gray-700 uppercase">
                ELO: {Math.round(comparisonData.team1.elo)}
              </div>
              <img
                src={comparisonData.team1.logo_url}
                className="h-32 w-32 object-contain mb-4 drop-shadow-2xl"
                alt=""
              />
              <h2 className="text-2xl md:text-3xl font-black uppercase tracking-tighter text-center text-white">
                {comparisonData.team1.name}
              </h2>
              <div className="flex gap-1.5 mt-4">
                {comparisonData.team1.stats.form.map((r, i) => (
                  <ResultCircle key={i} res={r} />
                ))}
              </div>
            </div>

            <span className="text-6xl font-black text-white opacity-10 italic my-8 md:my-0 uppercase">
              VS
            </span>

            <div className="flex flex-col items-center w-full md:w-2/5">
              <div className="text-[11px] font-black text-yellow-500 bg-gray-800 px-4 py-1.5 rounded-full mb-4 tracking-widest border border-gray-700 uppercase">
                ELO: {Math.round(comparisonData.team2.elo)}
              </div>
              <img
                src={comparisonData.team2.logo_url}
                className="h-32 w-32 object-contain mb-4 drop-shadow-2xl"
                alt=""
              />
              <h2 className="text-2xl md:text-3xl font-black uppercase tracking-tighter text-center text-white">
                {comparisonData.team2.name}
              </h2>
              <div className="flex gap-1.5 mt-4">
                {comparisonData.team2.stats.form.map((r, i) => (
                  <ResultCircle key={i} res={r} />
                ))}
              </div>
            </div>
          </div>

          {/* 3. ПРОГНОЗ НЕЙРОСЕТИ (ИНТЕГРИРОВАННЫЙ) */}
          {comparisonData.prediction && (
            <div className="bg-gray-900 rounded-[32px] p-8 md:p-12 mb-10 border border-gray-800 shadow-2xl relative overflow-hidden">
              <h2 className="text-sm md:text-base font-black text-white uppercase tracking-[0.3em] mb-10 text-center">
                Анализ Нейросети в реальном времени
              </h2>

              <div className="grid grid-cols-1 md:grid-cols-3 gap-8 items-stretch relative z-10">
                {/* Вероятности исхода */}
                <div className="bg-black/40 p-6 rounded-3xl border border-gray-800 flex flex-col justify-center">
                  <span className="text-[10px] font-black text-white uppercase tracking-widest block mb-4 text-center">
                    Шансы на победу
                  </span>
                  <div className="flex justify-between mb-3 text-[10px] md:text-xs font-black uppercase tracking-widest text-white">
                    <span>П1: {comparisonData.prediction.prob_home}%</span>
                    <span>X: {comparisonData.prediction.prob_draw}%</span>
                    <span>П2: {comparisonData.prediction.prob_away}%</span>
                  </div>
                  <div className="h-5 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                    <div
                      className="bg-green-500 h-full rounded-l-full"
                      style={{
                        width: `${comparisonData.prediction.prob_home}%`,
                      }}
                    ></div>
                    <div
                      className="bg-yellow-500 h-full"
                      style={{
                        width: `${comparisonData.prediction.prob_draw}%`,
                      }}
                    ></div>
                    <div
                      className="bg-red-600 h-full rounded-r-full"
                      style={{
                        width: `${comparisonData.prediction.prob_away}%`,
                      }}
                    ></div>
                  </div>
                </div>

                {/* Центральный блок: Прогноз от нейросети и Счет */}
                <div className="flex flex-col items-center justify-center p-6 bg-gray-800/30 rounded-3xl border border-gray-800">
                  <span className="text-[10px] font-black text-white opacity-60 uppercase tracking-widest mb-2 text-center">
                    Прогноз от нейросети
                  </span>
                  <span
                    className={`text-xl font-black uppercase mb-4 tracking-widest ${
                      comparisonData.prediction.outcome === "Win Home"
                        ? "text-green-500"
                        : comparisonData.prediction.outcome === "Win Away"
                          ? "text-red-600"
                          : "text-yellow-500"
                    }`}
                  >
                    {comparisonData.prediction.outcome === "Win Home"
                      ? "Победа П1"
                      : comparisonData.prediction.outcome === "Win Away"
                        ? "Победа П2"
                        : "Ничья (X)"}
                  </span>
                  <span className="text-6xl font-black text-white italic tracking-tighter">
                    {comparisonData.prediction.exact_score}
                  </span>
                </div>

                {/* Тотал */}
                <div className="bg-black/40 p-6 rounded-3xl border border-gray-800 flex flex-col justify-center">
                  <span className="text-[10px] font-black text-white uppercase tracking-widest block mb-4 text-center">
                    Вероятность тотала (2.5)
                  </span>
                  <div className="flex justify-between mb-3 text-[10px] md:text-xs font-black uppercase tracking-widest text-white">
                    <span>
                      БОЛЬШЕ: {comparisonData.prediction.total_over_2_5}%
                    </span>
                    <span>
                      МЕНЬШЕ:{" "}
                      {(100 - comparisonData.prediction.total_over_2_5).toFixed(
                        1,
                      )}
                      %
                    </span>
                  </div>
                  <div className="h-5 w-full bg-gray-800 rounded-full overflow-hidden flex p-0.5 border border-gray-700">
                    <div
                      className="bg-red-600 h-full rounded-l-full"
                      style={{
                        width: `${comparisonData.prediction.total_over_2_5}%`,
                      }}
                    ></div>
                    <div
                      className="bg-yellow-500 h-full rounded-r-full"
                      style={{
                        width: `${(100 - comparisonData.prediction.total_over_2_5).toFixed(1)}%`,
                      }}
                    ></div>
                  </div>
                </div>
              </div>
            </div>
          )}

          {/* 4. СТАТИСТИКА (АТАКА И ОБОРОНА С БЕЛЫМ ТЕКСТОМ) */}
          <div className="bg-gray-900 rounded-[32px] p-8 md:p-12 border border-gray-800 shadow-xl">
            <h2 className="text-sm md:text-base font-black text-white uppercase tracking-[0.3em] mb-12 text-center">
              Глубокое сравнение моделей игры
            </h2>

            <div className="grid grid-cols-1 md:grid-cols-2 gap-12 md:gap-20">
              <div className="space-y-8">
                <div className="text-center mb-6">
                  <span className="inline-block bg-green-500/10 border border-green-500/30 text-green-500 text-[11px] font-black uppercase tracking-widest px-6 py-2 rounded-full">
                    Атакующий потенциал
                  </span>
                </div>
                <StatBar
                  label="Забито голов"
                  h={comparisonData.team1.stats.gf}
                  a={comparisonData.team2.stats.gf}
                  color="bg-green-500"
                />
                <StatBar
                  label="Созданный xG"
                  h={comparisonData.team1.stats.xg_for}
                  a={comparisonData.team2.stats.xg_for}
                  color="bg-green-500"
                />
                <StatBar
                  label="Глубокие атаки"
                  h={comparisonData.team1.stats.deep}
                  a={comparisonData.team2.stats.deep}
                  color="bg-green-500"
                />
              </div>
              <div className="space-y-8">
                <div className="text-center mb-6">
                  <span className="inline-block bg-red-600/10 border border-red-600/30 text-red-500 text-[11px] font-black uppercase tracking-widest px-6 py-2 rounded-full">
                    Надежность обороны
                  </span>
                </div>
                <StatBar
                  label="Пропущено голов"
                  h={comparisonData.team1.stats.ga}
                  a={comparisonData.team2.stats.ga}
                  reverse
                  color="bg-red-600"
                />
                <StatBar
                  label="Допущенный xG"
                  h={comparisonData.team1.stats.xg_against}
                  a={comparisonData.team2.stats.xg_against}
                  reverse
                  color="bg-red-600"
                />
                <StatBar
                  label="Прессинг (PPDA)"
                  h={comparisonData.team1.stats.ppda}
                  a={comparisonData.team2.stats.ppda}
                  reverse
                  color="bg-red-600"
                />
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}

const StatBar = ({ label, h, a, reverse, color }) => {
  const isHomeBetter = reverse ? h < a : h > a;
  const total = h + a || 1;
  return (
    <div className="relative group">
      <div className="flex justify-between items-end mb-2">
        <span className="text-2xl font-black text-white">{h.toFixed(2)}</span>
        <span className="text-[10px] md:text-xs font-black text-white uppercase tracking-widest mb-1 text-center">
          {label}
        </span>
        <span className="text-2xl font-black text-white">{a.toFixed(2)}</span>
      </div>
      <div className="h-2.5 w-full bg-gray-800 rounded-full flex overflow-hidden p-0.5 border border-gray-700">
        <div
          className={`h-full rounded-full transition-all duration-1000 ${isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${(h / total) * 100}%` }}
        ></div>
        <div
          className={`h-full rounded-full transition-all duration-1000 ${!isHomeBetter ? color : "bg-gray-600"}`}
          style={{ width: `${(a / total) * 100}%` }}
        ></div>
      </div>
    </div>
  );
};

export default ComparePage;
